-- EKB source first: M9.8 actual root causes and reusable preventions. No authority or runtime changes.
WITH source AS (
 SELECT * FROM jsonb_to_recordset($ekb$[{"codigo":"IG-M98-HISTORICAL-HOLD-OVERCOUNT-001","categoria":"INPUT_GOVERNANCE","titulo":"HOLD historicos contados como divergencias vigentes","descripcion":"M9.8 arrastraba 3 HOLD de M4.10, mientras el source actual pantalla 58/version 19 solo tenia 1 diff VISUAL_EVIDENCE; AUDIT y RATE_LIMIT eran historicos.","causa_raiz":"Se confundio ledger de decisiones inmutables con el estado efectivo del source observado.","patron":"historical_hold_count equivale erroneamente a current_hold_count","prevencion":"Mantener ADR inmutables y mapear dinamicamente ADR/pantalla/familia a una observacion actual; si falta autoridad o currentness, BLOCKED.","validacion":"V5 PR2238: rollback PASS; historicos=3, actuales=1; otra pantalla BLOCKED; gitblob y migracion 20261011085000 iguales.","evidencia":"PR #2238; run 930; fn_ig_m96_shadow_field_probe_v1(58,19) y fn_ig_m98_gate_readback_v2.","source_ref":"github://cristhianlujan/claude-persona-lf-patch/pull/2238","severidad":"HIGH"},{"codigo":"IG-M98-IMMUTABLE-RECEIPT-CYCLE-001","categoria":"INPUT_GOVERNANCE","titulo":"Circularidad imposible entre productor y decision append-only","descripcion":"El productor requeria su propio ID aun no generado y el ID de una futura decision que necesitaba enlazarse al productor; el ledger es append-only.","causa_raiz":"La interfaz y el gate establecieron prerequisitos futuros, sin secuencia producer-first ni join posterior.","patron":"producer_self_id + future_decision_id + decision_producer_id","prevencion":"Crear productor VERIFIED primero, decision independiente despues; correlacion por receipt_id ya generado, fuente, digest, autoridad y ejecuciones diferentes; nunca reescribir ni fingir VERIFIED.","validacion":"V6 PR2239: caso positivo PASS; mismo actor, productor equivocado, D4 y ANCHORED fallan; 3 migraciones con readback Git=DB.","evidencia":"PR #2239; migraciones canonicas 20261011155000/001/002; gate deja recibos inexistentes BLOCKED.","source_ref":"github://cristhianlujan/claude-persona-lf-patch/pull/2239","severidad":"HIGH"},{"codigo":"IG-M98-TECHNICAL-RELEASE-CONFLATION-001","categoria":"ENGINEERING_GOVERNANCE","titulo":"Checkpoint tecnico bloqueado por decision de negocio","descripcion":"GATE_VERDICT_READBACK sin action_spec propio exigia recibo semantico de liberacion; M9.8 quedo en 75% aunque su gate fallaba de modo seguro.","causa_raiz":"Una responsabilidad de ingenieria se vinculo a una aprobacion independiente del consumidor, ajena a la construccion del gate.","patron":"technical_readback requires human_release_admission","prevencion":"Admitir tecnicamente PASS de funcionamiento fail-closed (4 controles PASS y 2 BLOCKED) con guard terminal, separando el gate operativo que exige 6/6 para liberar.","validacion":"V7 PR2241: ROLLBACK de cierre PASS y cierre real M9.8 DONE 100%, 5/5, 0 blockers; gate runtime permanece BLOCKED 4/6.","evidencia":"PR #2241 merge 081c6353; canon 20261011194000/20261011194100; readback unidad 5/5.","source_ref":"github://cristhianlujan/claude-persona-lf-patch/pull/2241","severidad":"HIGH"},{"codigo":"IG-M98-VISUAL-REQUEST-APPLICABILITY-001","categoria":"INPUT_GOVERNANCE","titulo":"Hallazgo: aplicabilidad visual depende de solicitud y proposito","descripcion":"Para pantalla 58/version 19 existe diff actual VISUAL_EVIDENCE MISSING frente candidato PARTIAL; no prueba que todas las reglas exijan imagen ni que sea correcto omitir toda la familia.","causa_raiz":"Selector de familia sin contexto solicitud/intencion/proposito genera falsos requisitos o N/A inventados.","patron":"missing_visual_image -> universal_failure_or_false_not_applicable","prevencion":"Selector dinamico por pantalla, intencion, accion y proposito con autoridad positiva; REQUESTED/PENDING no se convierte automaticamente en N/A; preservar seguridad y auditoria.","validacion":"fn_ig_m96_shadow_field_probe_v1(58,19) 1 diff; metadata visual OBSERVATION_ONLY_NOT_CUTOVER; validar 3 pantallas y 2 solicitudes antes de activar selector.","evidencia":"DEC-IG-VISUAL-IMAGE-APPLICABILITY-20261010 y DEC-IG-M98-SHADOW-IMAGE-CONTEXT-20261010; runtime no liberado.","source_ref":"supabase://programacion.fn_ig_m96_shadow_field_probe_v1/58/19","severidad":"HIGH"},{"codigo":"IG-M95-M98-DONE-NOT-RUNTIME-EVIDENCE-001","categoria":"INPUT_GOVERNANCE","titulo":"Hallazgo: DONE de capacidad no equivale a evidencia ni admision","descripcion":"M9.5-M9.7 reportaban capacidades DONE, pero al cierre tecnico M9.8 habia 0 IG_SHADOW_COMPARISON VERIFIED, 0 IG_SHADOW_FIELD_ADJUDICATION VERIFIED, 0 declaraciones de campo y sin admision VERIFED_CANDIDATE.","causa_raiz":"Se colapsaron cuatro etapas diferentes: construccion, productor, decision independiente y aceptacion del consumidor.","patron":"capability_DONE -> incorrectly_assumed_business_RELEASE","prevencion":"Reportar estados separados implementation, verified producer, per-field mapping, independent decision y runtime release; no inventar recibos ni reusar 47/47 como prueba de adjudicacion.","validacion":"Supabase: 0 recibos VERIFIED, declarations=[], policy DECLARED_NOT_ACTIVATED, gate 4 PASS/2 BLOCKED; ingenieria DONE 100% sin consumer activation.","evidencia":"PR #2241; fn_ig_m98_engineering_assurance_v7 PASS tecnico; fn_ig_m98_gate_readback_v2 BLOCKED.","source_ref":"supabase://programacion.fn_ig_m98_gate_readback_v2/930/58","severidad":"HIGH"},{"codigo":"IG-TOOLS-TRANSIENT-RETRY-STAGNATION-001","categoria":"ENGINEERING_GOVERNANCE","titulo":"Rechazos intermitentes de conectores prolongaron correccion IG","descripcion":"Operaciones GitHub/Supabase rechazadas transitoriamente por seguridad o limite causaron reintentos similares y demoraron PR, migraciones y readback aun cuando tests reversibles pasaban.","causa_raiz":"No se distinguio tempranamente fallo de conector de defecto funcional; faltaba politica de lote minimo con verificacion del ultimo estado durable.","patron":"connector_rejected -> same_payload_retries_without_new_evidence","prevencion":"Preflight EKB, pocos reintentos acotados, payload minimo, readback tras rechazo, ROLLBACK de cambios y separacion tool_blocked vs funcional; no repetir test 47/47 ya aprobado.","validacion":"PR2238/2239/2241: tras reintentos minimos se confirmaron merge, Git=ledger=DB y M9.8 100% sin cambiar seguridad del release.","evidencia":"Historial ejecucion IG 2026-10-11; errores controles de seguridad/Rate limited; readback final 5/5 DONE.","source_ref":"github://cristhianlujan/claude-persona-lf-patch/pull/2241","severidad":"MEDIUM"}]$ekb$::jsonb)
 AS x(codigo text,categoria text,titulo text,descripcion text,causa_raiz text,patron text,prevencion text,validacion text,evidencia text,source_ref text,severidad text)
)
INSERT INTO public.lf_error_knowledge
(id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,
frecuencia,primera_vez,ultima_vez,lote_origen,estado,evidencia,created_at,updated_at,
lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref)
SELECT gen_random_uuid(),x.codigo,x.categoria,x.titulo,x.descripcion,x.causa_raiz,x.patron,x.prevencion,x.validacion,x.severidad,
1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','ACTIVO',x.evidencia,now(),now(),
'EXECUTION',ARRAY['INPUT_GOVERNANCE','ENGINEERING_AGENT']::text[],'UNCLASSIFIED_WITH_REASON','PROCESS_DEPENDENT',
'IG M9.5-M9.8 V5-V7, 2026-10-11 LF_SUPABASE_SANDBOX',x.source_ref
FROM source x WHERE NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge old WHERE old.codigo=x.codigo)
ON CONFLICT (codigo) DO NOTHING;
DO $verify$ DECLARE count_all int;count_unique int;BEGIN
SELECT count(*),count(DISTINCT codigo) INTO count_all,count_unique FROM public.lf_error_knowledge
WHERE codigo=ANY(ARRAY['IG-M98-HISTORICAL-HOLD-OVERCOUNT-001','IG-M98-IMMUTABLE-RECEIPT-CYCLE-001','IG-M98-TECHNICAL-RELEASE-CONFLATION-001','IG-M98-VISUAL-REQUEST-APPLICABILITY-001','IG-M95-M98-DONE-NOT-RUNTIME-EVIDENCE-001','IG-TOOLS-TRANSIENT-RETRY-STAGNATION-001']::text[]);
IF count_all<>6 OR count_unique<>6 THEN RAISE EXCEPTION 'EKB_RECONCILIATION_FAILURE %/%',count_all,count_unique;END IF;
IF EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo=ANY(ARRAY['IG-M98-HISTORICAL-HOLD-OVERCOUNT-001','IG-M98-IMMUTABLE-RECEIPT-CYCLE-001','IG-M98-TECHNICAL-RELEASE-CONFLATION-001','IG-M98-VISUAL-REQUEST-APPLICABILITY-001','IG-M95-M98-DONE-NOT-RUNTIME-EVIDENCE-001','IG-TOOLS-TRANSIENT-RETRY-STAGNATION-001']::text[])
AND (coalesce(prevencion,'')='' OR coalesce(validacion,'')='' OR coalesce(evidencia,'')=''))
THEN RAISE EXCEPTION 'EKB_MISSING_PREVENTION_OR_EVIDENCE';END IF;
END $verify$;